import json
import re
import datetime

ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
CUR = [
    ('TL', 'debtTL', 'Türk Lirası', 'lira', 'kuruş'),
    ('USD', 'debtUSD', 'Dolar', 'dolar', 'sent'),
    ('EUR', 'debtEUR', 'Euro', 'euro', 'sent'),
    ('GBP', 'debtGBP', 'İngiliz Sterlini', 'İngiliz Sterlini', 'peni'),
]
BAD_NAME = re.compile(r'(talimat|yok say|ignore|instruction|oku|söyle|prompt|sistem|kural|numara)', re.I)


def V():
    try:
        v = vars
        if isinstance(v, dict):
            return v
    except Exception:
        pass
    return {}


def three(n):
    out = []
    h = n // 100
    r = n % 100
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        out.append(TENS[r // 10])
    if r % 10:
        out.append(ONES[r % 10])
    return ' '.join(out)


def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        g = n // size
        n = n % size
        if g:
            if name == 'bin' and g == 1:
                parts.append('bin')
            else:
                parts.append(three(g) + ' ' + name)
    if n:
        parts.append(three(n))
    return ' '.join(parts)


def num(x):
    try:
        return float(x)
    except Exception:
        return None


def money(x, code):
    f = num(x)
    if f is None:
        return ''
    c = [r for r in CUR if r[0] == code][0]
    cents = int(round(abs(f) * 100))
    whole = cents // 100
    frac = cents % 100
    if frac == 0:
        unit = c[2] if code == 'TL' else c[3]
        return words(whole) + ' ' + unit
    if whole == 0:
        return words(frac) + ' ' + c[4]
    return words(whole) + ' ' + c[3] + ' ' + words(frac) + ' ' + c[4]


def digits(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())


def pdate(s):
    m = re.match(r'\s*(\d{1,2})\.(\d{1,2})\.(\d{4})', str(s or ''))
    if not m:
        return None
    try:
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None


def sdate(d):
    if not d:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)


def cop(d):
    y = d.year % 10
    t = (d.year // 10) % 10
    if y == 0:
        return {1: 'dur', 2: 'dir', 3: 'dur', 4: 'tır', 5: 'dir'}.get(t, 'dir')
    return {1: 'dir', 2: 'dir', 3: 'tür', 4: 'tür', 5: 'tir', 6: 'dır', 7: 'dir', 8: 'dir', 9: 'dur'}[y]


def today():
    v = V()
    m = re.match(r'\s*(\d{4})-(\d{2})-(\d{2})', str(v.get('now') or ''))
    if m:
        try:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except Exception:
            pass
    return None


def clean_name(n):
    n = str(n or '').strip()
    if not n or len(n) > 40 or BAD_NAME.search(n):
        return ''
    return n


def tree(prefix):
    """Rebuild a nested dict from flattened keys that start with prefix."""
    v = V()
    root = {}
    for k in list(v.keys()):
        ks = str(k)
        if not ks.startswith(prefix):
            continue
        rest = ks[len(prefix):]
        if not rest:
            continue
        parts = rest.split('.')
        cur = root
        for p in parts[:-1]:
            nxt = cur.get(p)
            if not isinstance(nxt, dict):
                nxt = dict()
                cur[p] = nxt
            cur = nxt
        cur[parts[-1]] = v.get(k)
    return root


def as_list(x):
    if isinstance(x, list):
        return x
    if isinstance(x, dict):
        keys = [k for k in x.keys() if str(k).isdigit()]
        if keys:
            return [x[k] for k in sorted(keys, key=lambda s: int(s))]
    if isinstance(x, str) and x.strip()[:1] in ('[', '{'):
        for s in (x, x.replace("'", '"').replace('True', 'true').replace('False', 'false').replace('None', 'null')):
            try:
                return as_list(json.loads(s))
            except Exception:
                pass
    return []


def load_json(key):
    v = V()
    x = v.get(key)
    if isinstance(x, dict):
        return x
    if isinstance(x, str) and x.strip()[:1] == '{':
        try:
            return json.loads(x)
        except Exception:
            return None
    return None


def body_of(name):
    """API body (the dict with data/result) of a call, from the hook copy or the flattened keys."""
    b = load_json('hk_' + name)
    try:
        V()['hk_' + name] = ''
    except Exception:
        pass
    if isinstance(b, dict) and b:
        return b
    t = tree(name + '_response.data.')
    return t if t else None


def ok_body(b):
    try:
        return str(b.get('result', dict()).get('returnCode')) == '1' and isinstance(b.get('data'), dict)
    except Exception:
        return False


def get_cards():
    cards = as_list(V().get('cards_json'))
    if cards:
        return [c for c in cards if isinstance(c, dict)]
    b = body_of('cards_list') or dict()
    d = b.get('data') if isinstance(b, dict) else None
    if isinstance(d, dict):
        return [c for c in as_list(d.get('cards')) if isinstance(c, dict)]
    return []

