            if first:
                s = opening + s
                first = False
            out.append(s)
        if clear:
            if len(clear) == 1:
                out.append(clear[0] + ' borcunuz bulunmamaktadır.')
            else:
                out.append(', '.join(clear[:-1]) + ' ve ' + clear[-1] + ' borcunuz bulunmamaktadır.')
        if due:
            if t and t == due:
                out.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            else:
                out.append('Borçlarınız için son ödeme tarihiniz ' + sdate(due) + "'" + cop(due) + '.')
    v['reading_text'] = ' '.join(out)
    v['read_kind'] = kind
    v['read_state'] = 'ok'

try:
    compose()
except Exception as e:
    try:
        vv = V()
        vv['read_state'] = 'error'
        vv['reading_text'] = vv.get('reading_text') or ''
        vv['code_error'] = str(e)
    except Exception:
        pass

